<script>
const tStore=@json(route('transfers-store')),tUpdate=@json(route('transfers-update','__ID__')),tStatus=@json(route('transfers-status','__ID__'));function td(x){return x?JSON.parse(atob(x)):{}}function filterTransferSelects(){let f=document.getElementById('transferForm'),b=f.elements.to_branch_id.value,d=f.elements.to_department_id;[...d.options].forEach((o,i)=>{if(i)o.hidden=o.dataset.branch!==b});if(d.selectedOptions[0]?.hidden)d.value='';let g=f.elements.to_designation_id;[...g.options].forEach((o,i)=>{if(i)o.hidden=o.dataset.department!==d.value});if(g.selectedOptions[0]?.hidden)g.value=''}
function openTransfer(mode,x){let f=document.getElementById('transferForm'),d=td(x);f.reset();f.action=tStore;document.getElementById('transferMethod').innerHTML='';document.getElementById('transferTitle').textContent=mode==='edit'?'Edit Transfer':'Add New Transfer';['employee_id','to_branch_id','to_department_id','to_designation_id','transfer_date','effective_date','reason','status','notes'].forEach(k=>f.elements[k].value=d[k]|| (k==='status'?'Pending':''));filterTransferSelects();if(mode==='edit'){f.action=tUpdate.replace('__ID__',d.id);document.getElementById('transferMethod').innerHTML='<input type="hidden" name="_method" value="PUT">'}}
function viewTransfer(x){let d=td(x),m=document.getElementById('transferView'),pairs=[['Branch',d.from_branch,d.to_branch],['Department',d.from_department,d.to_department],['Designation',d.from_designation,d.to_designation]];document.getElementById('transferChanges').innerHTML=pairs.map(p=>'<div class="mb-4"><div class="text-muted mb-2">'+p[0]+' Transfer</div><div class="change-grid"><div class="change-box"><small>From</small><strong class="d-block">'+(p[1]||'—')+'</strong></div><div class="change-arrow">→</div><div class="change-box to"><small>To</small><strong class="d-block">'+(p[2]||'—')+'</strong></div></div></div>').join('');['transfer_date','effective_date','reason','notes'].forEach(k=>m.querySelector('[data-tv='+k+']').textContent=d[k]||'—');m.querySelector('[data-tv=status]').innerHTML='<span class="transfer-status '+d.status.toLowerCase()+'">'+d.status+'</span>'}function openTransferStatus(id,s){let f=document.getElementById('transferStatusForm');f.action=tStatus.replace('__ID__',id);f.elements.status.value=s}
document.addEventListener('DOMContentLoaded',()=>{let f=document.getElementById('transferForm');f.elements.to_branch_id.onchange=filterTransferSelects;f.elements.to_department_id.onchange=filterTransferSelects;let rules={employee_id:'Employee',to_branch_id:'To Branch',to_department_id:'To Department',transfer_date:'Transfer Date',effective_date:'Effective Date',reason:'Reason',status:'Status'};f.onsubmit=e=>{f.querySelectorAll('.transfer-error').forEach(x=>x.remove());f.querySelectorAll('.transfer-invalid').forEach(x=>x.classList.remove('transfer-invalid'));let first;Object.entries(rules).forEach(([k,n])=>{let x=f.elements[k],msg=!x.value?n+' is required':(k==='effective_date'&&f.elements.transfer_date.value&&x.value<f.elements.transfer_date.value?'Effective Date must be after or equal to Transfer Date':'');if(msg){x.classList.add('transfer-invalid');x.insertAdjacentHTML('afterend','<div class="transfer-error">'+msg+'</div>');first=first||x}});if(first){e.preventDefault();first.focus()}}});
</script>
<script>
function openTransferDecision(id,status){var f=document.getElementById('transferStatusForm'),modal=document.getElementById('transferStatus'),reject=status==='Rejected';f.action=tStatus.replace('__ID__',id);modal.querySelector('.modal-header h2').textContent=reject?'Reject Transfer':'Approve Transfer';modal.querySelector('.modal-body').innerHTML='<input type="hidden" name="status" value="'+status+'"><label class="form-label'+(reject?' required':'')+'">'+(reject?'Rejection Reason':'Notes')+'</label><textarea class="form-control" name="notes" rows="3" placeholder="'+(reject?'Enter rejection reason...':'Enter approval notes...')+'"></textarea>';f.onsubmit=function(e){var notes=f.elements.notes;if(reject&&!notes.value.trim()){e.preventDefault();notes.classList.add('transfer-invalid');var old=notes.parentNode.querySelector('.transfer-error');if(!old){old=document.createElement('div');old.className='transfer-error';notes.after(old)}old.textContent='Rejection Reason is required';notes.focus()}}}
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('button[onclick^="openTransferStatus"]').forEach(function(old){var id=old.dataset.id,status=old.dataset.status;if(status!=='Pending'){old.remove();return}var approve=document.createElement('button'),reject=document.createElement('button');approve.type=reject.type='button';approve.className=reject.className='transfer-action';approve.title='Approve';reject.title='Reject';approve.dataset.bsToggle=reject.dataset.bsToggle='modal';approve.dataset.bsTarget=reject.dataset.bsTarget='#transferStatus';approve.innerHTML='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16 9"/></svg>';reject.innerHTML='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m9 9 6 6m0-6-6 6"/></svg>';approve.onclick=function(){openTransferDecision(id,'Approved')};reject.onclick=function(){openTransferDecision(id,'Rejected')};old.replaceWith(approve,reject)});document.querySelectorAll('form[action*="/transfers/"][method="POST"]').forEach(function(form){if(!form.querySelector('input[name="_method"][value="DELETE"]'))return;var deleteButton=form.querySelector('button');if(deleteButton){deleteButton.title='Delete';deleteButton.innerHTML='<svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/></svg>'}form.onsubmit=function(e){if(form.dataset.confirmed)return;e.preventDefault();var name=form.closest('tr')?.querySelector('.transfer-person strong')?.textContent||'this employee';Swal.fire({title:'Delete transfer',html:'Are you sure you want to delete '+name+'? This action cannot be undone.',icon:'warning',showCancelButton:true,confirmButtonText:'Delete',cancelButtonText:'Cancel',buttonsStyling:false,customClass:{confirmButton:'btn btn-danger',cancelButton:'btn btn-light me-3'},reverseButtons:true}).then(function(r){if(r.isConfirmed){form.dataset.confirmed='1';form.submit()}})}})});
</script>
<script>
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.transfer-table tbody tr').forEach(function(row){if(row.querySelector('.transfer-status')?.textContent.trim()!=='Approved')return;row.querySelectorAll('td:last-child button,td:last-child form').forEach(function(item){var button=item.matches('button')?item:item.querySelector('button');if(button?.title!=='View')item.remove()})})});
</script>
